const crypto = require('crypto');
const CFG = {"brand": "Sentinel AI", "from_email": "support@visioncoders.online", "site": "eagleseye.microeagle.online", "otp_ttl_minutes": 10, "reset_ttl_minutes": 30, "max_otp_attempts": 5, "resend_cooldown_seconds": 60, "max_login_failures": 8, "lock_minutes": 15, "min_password_length": 8, "allowed_email_domains": ["gmail.com"], "terms_version": "v1.0", "notify_key": "4lKijUvVQv1nmuVcjoqGg_lw1lrSOuw3oNePGP_aBVI", "site_origin": "https://eagleseye.microeagle.online", "twilio_number": "+14154497491"};

// scrypt, not SHA: a password hash must be SLOW. These parameters cost about
// 16MB and ~100ms per guess, which is invisible to one user logging in and
// ruinous to someone grinding a stolen database.
const SCRYPT = { N: 16384, r: 8, p: 1 };
const ALGO = 'scrypt-16384-8-1';

function hashPassword(pw) {
  const salt = crypto.randomBytes(16).toString('hex');
  const key = crypto.scryptSync(pw, salt, 64, SCRYPT).toString('hex');
  return { pw_salt: salt, pw_hash: key, pw_algo: ALGO };
}

function checkPassword(pw, salt, expected) {
  if (!pw || !salt || !expected) return false;
  const got = crypto.scryptSync(pw, salt, 64, SCRYPT);
  const want = Buffer.from(String(expected), 'hex');
  // Length must match before timingSafeEqual, which throws on a mismatch.
  return got.length === want.length && crypto.timingSafeEqual(got, want);
}

// Tokens are short-lived and high-entropy, so a single fast hash is right here
// -- the point is only that a database leak cannot be replayed.
function tokenHash(value, salt) {
  return crypto.createHash('sha256').update(String(salt) + ':' + String(value))
               .digest('hex');
}

function sameHash(a, b) {
  const x = Buffer.from(String(a));
  const y = Buffer.from(String(b));
  return x.length === y.length && crypto.timingSafeEqual(x, y);
}

function newOtp() {
  // rejection-free: 6 digits from a uniform 32-bit draw is close enough to
  // uniform that the bias is far below anything an attacker can exploit.
  return String(crypto.randomInt(0, 1000000)).padStart(6, '0');
}

function newToken() { return crypto.randomBytes(32).toString('hex'); }

function normEmail(v) { return String(v || '').trim().toLowerCase(); }

function normPhone(v) {
  // Accept +91..., 91..., 0..., or the bare ten digits: a farmer types all of
  // these and they must all reach the same account.
  const d = String(v || '').replace(/[^0-9]/g, '');
  return d.replace(/^0+/, '').replace(/^91/, '');
}

function validPhone(v) {
  return /^[6-9]\d{9}$/.test(normPhone(v));
}

function e164(v) { return '+91' + normPhone(v); }

function validEmail(v) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v) && v.length <= 254;
}

// Deliberately not a complexity-class rule. Length beats character classes,
// and blocking the handful of obvious choices catches most real bad passwords.
function passwordProblem(pw) {
  const p = String(pw || '');
  if (p.length < CFG.min_password_length) {
    return 'Password must be at least ' + CFG.min_password_length + ' characters.';
  }
  if (p.length > 200) return 'Password is too long.';
  if (/^(.)\1+$/.test(p)) return 'Password cannot be a single repeated character.';
  const weak = ['password', '12345678', 'qwertyui', 'iloveyou', 'admin123',
                'letmein1', '11111111', 'sentinelai'];
  if (weak.includes(p.toLowerCase())) return 'That password is too common.';
  return '';
}

function minutesFromNow(m) {
  return new Date(Date.now() + Number(m) * 60000).toISOString();
}

