}


const b = body();
const email = normEmail(b.email);
const phone = normPhone(b.phone || b.mobile);
const name = String(b.name || '').trim().slice(0, 80);

// --- Sentinel ----------------------------------------------------------
// An account belongs to ONE organisation of a known kind; operators only
// ever see their own organisation's cameras and incidents. The terms must
// be accepted before any record is created.
const ACCOUNT_TYPES = ["airport", "railway_station", "metro_station", "bus_terminal", "stadium", "mall", "campus", "police", "event", "other"];
const accountType = String(b.account_type || '').trim().toLowerCase();
const organisation = String(b.organisation || '').trim().slice(0, 120);
const siteLabel = String(b.site_label || '').trim().slice(0, 120);
if (!ACCOUNT_TYPES.includes(accountType)) {
  return [{ json: { ok: false, status: 400,
    error: 'Choose the kind of site this account is for.' } }];
}
if (organisation.length < 2) {
  return [{ json: { ok: false, status: 400,
    error: 'Organisation name is required.' } }];
}
if (b.terms_accepted !== true && String(b.terms_accepted) !== 'true') {
  return [{ json: { ok: false, status: 400,
    error: 'You must accept the Terms and Conditions to register.' } }];
}


if (!validEmail(email)) {
  return [{ json: { ok: false, status: 400, error: 'A valid email is required.' } }];
}

// Throwaway inboxes defeat the point of verifying an address at all, so
// registration is limited to the domains in CFG.allowed_email_domains.
const allowedDomains = CFG.allowed_email_domains || [];
if (allowedDomains.length &&
    !allowedDomains.some(function (d) { return email.endsWith('@' + d); })) {
  return [{ json: { ok: false, status: 400,
    error: 'Please register with a Gmail address (' +
           allowedDomains.join(', ') + ').' } }];
}

// Both are required. The same code is sent to each, so whichever arrives
// first is the one they type -- a mistyped email no longer strands anyone.
if (!validPhone(phone)) {
  return [{ json: { ok: false, status: 400,
    error: 'A valid 10-digit Indian mobile number is required.' } }];
}
const pwErr = passwordProblem(b.password);
if (pwErr) return [{ json: { ok: false, status: 400, error: pwErr } }];

const pw = hashPassword(b.password);
const otp = newOtp();
const linkToken = newToken();
const salt = crypto.randomBytes(16).toString('hex');

return [{ json: {
  ok: true, email, name, phone, phone_e164: e164(phone),
  account_type: accountType, organisation, site_label: siteLabel,
  terms_version: CFG.terms_version, terms_accepted_at: new Date().toISOString(),
  ...pw,
  otp,                                   // emailed, never stored or returned
  link_token: linkToken,                 // emailed, never stored or returned
  token_salt: salt,
  otp_hash: tokenHash(otp, salt),
  link_hash: tokenHash(linkToken, salt),
  expires_at: minutesFromNow(CFG.otp_ttl_minutes),
  verify_url: "https://n8n-kmar.srv1804200.hstgr.cloud/webhook" + '/sentinel/verify-link?token=' + linkToken
              + '&email=' + encodeURIComponent(email),
} }];

