let found = null;
try {
  const r = $('Find Signup User').first().json;
  if (r && r.email) found = r;
} catch (e) {}

if (found && found.verified) {
  return [{ json: { ...req, mode: 'exists', status: 409,
    error: 'That email is already registered. Try signing in, or use forgot password.' } }];
